// Datos y Assets Institucionales Oficiales
// Ministerio de Seguridad - Provincia de Buenos Aires
// Superintendencia de Investigaciones de Delitos Complejos y Crimen Organizado

export const INSTITUCIONAL_INFO = {
  ministerio: "Ministerio de Seguridad de la Provincia de Buenos Aires",
  ministerioCorto: "Ministerio de Seguridad · PBA",
  superintendencia: "Superintendencia de Investigaciones de Delitos Complejos y Crimen Organizado",
  superintendenciaCorta: "Superintendencia de Investigaciones de Delitos Complejos",
  direccion: "Avenida 52 S/N entre 117 y 118 – Paseo del Bosque de La Plata (C.P. N° 1900)",
  telefono: "(0221) 423-1867/186",
  seguridad: "Documento Reservado · Inteligencia Criminal y Apoyo Pericial Judicial",
  ley: "Ley de Personal Policial N° 13.482 · Sistema Integrado de Geointeligencia 911",
};

export const LOGO_SUPERINTENDENCIA_BASE64 = "data:image/png;base64,";
export const LOGO_MINISTERIO_BASE64 = "data:image/svg+xml;base64,";

/**
 * Retorna el bloque HTML del encabezado institucional oficial para reportes PDF
 */
export function getInstitucionalHeaderHTML(options?: {
  themeColor?: string;
}): string {
  const color = options?.themeColor || "#1e3a8a";
  return `
    <div style="display: flex; align-items: center; justify-content: space-between; border-bottom: 2px solid #cbd5e1; padding-bottom: 12px; margin-bottom: 16px; background: #ffffff; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">
      <div style="display: flex; align-items: center; gap: 14px;">
        <img src="${LOGO_MINISTERIO_BASE64}" alt="Ministerio de Seguridad PBA" style="height: 52px; width: auto; max-width: 150px; object-fit: contain;" />
        <div style="border-left: 1.5px solid #cbd5e1; height: 42px; margin: 0 4px;"></div>
        <img src="${LOGO_SUPERINTENDENCIA_BASE64}" alt="Superintendencia de Investigaciones" style="height: 50px; width: auto; object-fit: contain;" />
      </div>

      <div style="text-align: right; line-height: 1.35;">
        <div style="font-size: 10px; font-weight: 800; color: #1e293b; text-transform: uppercase; letter-spacing: 0.6px;">
          ${INSTITUCIONAL_INFO.ministerio}
        </div>
        <div style="font-size: 11px; font-weight: 900; color: ${color}; text-transform: uppercase; letter-spacing: 0.4px; margin-top: 1px;">
          ${INSTITUCIONAL_INFO.superintendencia}
        </div>
        <div style="font-size: 8.5px; color: #64748b; margin-top: 2px;">
          ${INSTITUCIONAL_INFO.direccion} · Tel. ${INSTITUCIONAL_INFO.telefono}
        </div>
      </div>
    </div>
  `;
}

/**
 * Retorna el bloque HTML del pie institucional oficial para reportes PDF
 */
export function getInstitucionalFooterHTML(): string {
  return `
    <div style="margin-top: 26px; padding-top: 12px; border-top: 2px solid #e2e8f0; display: flex; justify-content: space-between; align-items: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-size: 8px; color: #64748b; line-height: 1.4;">
      <div style="display: flex; align-items: center; gap: 10px;">
        <img src="${LOGO_MINISTERIO_BASE64}" alt="Ministerio PBA" style="height: 22px; width: auto; opacity: 0.85;" />
        <img src="${LOGO_SUPERINTENDENCIA_BASE64}" alt="Superintendencia PBA" style="height: 22px; width: auto; opacity: 0.85;" />
        <div>
          <strong style="color: #334155; font-size: 8.5px;">${INSTITUCIONAL_INFO.superintendencia}</strong><br/>
          ${INSTITUCIONAL_INFO.direccion} · Tel. ${INSTITUCIONAL_INFO.telefono}
        </div>
      </div>
      <div style="text-align: right;">
        <span style="font-weight: 700; color: #475569;">${INSTITUCIONAL_INFO.seguridad}</span><br/>
        ${INSTITUCIONAL_INFO.ley}
      </div>
    </div>
  `;
}
